export const respondToImpact = async (impactId: number,
    impactResponseInput: ImpactResponseInput, options?: RequestInit): Promise<MilestoneImpact> => {

  return customFetch<MilestoneImpact>(getRespondToImpactUrl(impactId),
  {
    ...options,
    method: 'POST',
    headers: { 'Content-Type': 'application/json', ...options?.headers },
    body: JSON.stringify(
      impactResponseInput,)
  }
);}




export const getRespondToImpactMutationOptions = <TError = ErrorType<ErrorResponse>,
    TContext = unknown>(options?: { mutation?:UseMutationOptions<Awaited<ReturnType<typeof respondToImpact>>, TError,{impactId: number;data: BodyType<ImpactResponseInput>}, TContext>, request?: SecondParameter<typeof customFetch>}
): UseMutationOptions<Awaited<ReturnType<typeof respondToImpact>>, TError,{impactId: number;data: BodyType<ImpactResponseInput>}, TContext> => {

const mutationKey = ['respondToImpact'];
const {mutation: mutationOptions, request: requestOptions} = options ?
      options.mutation && 'mutationKey' in options.mutation && options.mutation.mutationKey ?
      options
      : {...options, mutation: {...options.mutation, mutationKey}}
      : {mutation: { mutationKey, }, request: undefined};




      const mutationFn: MutationFunction<Awaited<ReturnType<typeof respondToImpact>>, {impactId: number;data: BodyType<ImpactResponseInput>}> = (props) => {
          const {impactId,data} = props ?? {};

          return  respondToImpact(impactId,data,requestOptions)
        }






  return  { mutationFn, ...mutationOptions }}

    export type RespondToImpactMutationResult = NonNullable<Awaited<ReturnType<typeof respondToImpact>>>
    export type RespondToImpactMutationBody = BodyType<ImpactResponseInput>
    export type RespondToImpactMutationError = ErrorType<ErrorResponse>

    /**
 * @summary Submit a response to an impact notification
 */
export const useRespondToImpact = <TError = ErrorType<ErrorResponse>,
    TContext = unknown>(options?: { mutation?:UseMutationOptions<Awaited<ReturnType<typeof respondToImpact>>, TError,{impactId: number;data: BodyType<ImpactResponseInput>}, TContext>, request?: SecondParameter<typeof customFetch>}
 ): UseMutationResult<
        Awaited<ReturnType<typeof respondToImpact>>,
        TError,
        {impactId: number;data: BodyType<ImpactResponseInput>},
        TContext
      > => {
      return useMutation(getRespondToImpactMutationOptions(options));
    }

